begin;
select no_plan();
select ok(has_table_privilege('service_role','public.active_families','select'),'Edge auth can verify the selected family');
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001301','a13@test.local'),('00000000-0000-4000-8000-000000001302','b13@test.local'),('00000000-0000-4000-8000-000000001303',null);
insert into public.families(id,name,created_by,invite_code) values('10000000-0000-4000-8000-000000001301','A','00000000-0000-4000-8000-000000001301','FA13AA01'),('10000000-0000-4000-8000-000000001302','B','00000000-0000-4000-8000-000000001302','FA13AA02');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000001301','00000000-0000-4000-8000-000000001301'),('10000000-0000-4000-8000-000000001302','00000000-0000-4000-8000-000000001302');
insert into public.children(id,family_id,name) values('20000000-0000-4000-8000-000000001301','10000000-0000-4000-8000-000000001301','Ece'),('20000000-0000-4000-8000-000000001302','10000000-0000-4000-8000-000000001301','Can'),('20000000-0000-4000-8000-000000001303','10000000-0000-4000-8000-000000001302','Other');
insert into public.devices(id,family_id,auth_user_id) values('30000000-0000-4000-8000-000000001301','10000000-0000-4000-8000-000000001301','00000000-0000-4000-8000-000000001303');
set local role authenticated;
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001301", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001301", "role": "parent", "device_id": null, "child_id": null}}',true);
select throws_ok($$select public.configure_child_device('30000000-0000-4000-8000-000000001301','Tablet',array['20000000-0000-4000-8000-000000001301']::uuid[],true)$$,'P0001','child_pin_required','required PIN cannot silently bypass missing PIN');
select public.set_child_pin('20000000-0000-4000-8000-000000001301','1234');
select public.configure_child_device('30000000-0000-4000-8000-000000001301','Ece tablet',array['20000000-0000-4000-8000-000000001301']::uuid[],true);
select throws_ok($$select public.configure_child_device('30000000-0000-4000-8000-000000001301','Tablet',array['20000000-0000-4000-8000-000000001303']::uuid[],false)$$,'P0001','child_not_found','cannot whitelist child in another family');
select throws_ok($$update public.devices set pin_policy='none' where id='30000000-0000-4000-8000-000000001301'$$,'42501',null,'direct device write cannot bypass validation');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001303", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001301", "role": "device", "device_id": "30000000-0000-4000-8000-000000001301", "child_id": null}}',true);
select is((select count(*)::int from public.children),1,'only assigned child visible');
select is(public.child_pin_login('20000000-0000-4000-8000-000000001301','0000'),false,'wrong PIN fails');
select is(public.child_pin_login('20000000-0000-4000-8000-000000001301','1234'),true,'right PIN enters');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001303", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001301", "role": "device", "device_id": "30000000-0000-4000-8000-000000001301", "child_id": "20000000-0000-4000-8000-000000001301"}}',true);
select throws_ok($$select public.child_pin_login('20000000-0000-4000-8000-000000001302','1234')$$,'42501','forbidden','unassigned sibling denied at server');
select throws_ok($$select public.configure_child_device('30000000-0000-4000-8000-000000001301','Hack',array['20000000-0000-4000-8000-000000001302']::uuid[],false)$$,'42501','forbidden','child cannot change device access');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001301", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001301", "role": "parent", "device_id": null, "child_id": null}}',true);
select public.configure_child_device('30000000-0000-4000-8000-000000001301','Shared',array['20000000-0000-4000-8000-000000001301','20000000-0000-4000-8000-000000001302']::uuid[],false);
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001303", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001301", "role": "device", "device_id": "30000000-0000-4000-8000-000000001301", "child_id": "20000000-0000-4000-8000-000000001301"}}',true);
select is(gina.is_device(),false,'old active-child JWT invalid after config change');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001303", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001301", "role": "device", "device_id": "30000000-0000-4000-8000-000000001301", "child_id": null}}',true);
select is((select count(*)::int from public.children),2,'shared device exposes selected siblings');
select is(public.child_pin_login('20000000-0000-4000-8000-000000001302',''),true,'explicit PIN-free mode enters without PIN');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001301", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001301", "role": "parent", "device_id": null, "child_id": null}}',true);
select is(public.preview_family_invite('FA13AA02')->>'name','B','valid code previews target family');
select is(public.join_family('FA13AA02'),'10000000-0000-4000-8000-000000001302'::uuid,'existing parent joins partner family without deletion');
select is(gina.is_parent(),false,'old family JWT invalidated on switch');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001301", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001302", "role": "parent", "device_id": null, "child_id": null}}',true);
select is(jsonb_array_length(public.list_my_families()),2,'both memberships preserved');
select is((select count(*)::int from public.children),1,'new family RLS active');
select public.select_family('10000000-0000-4000-8000-000000001301');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001301", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001301", "role": "parent", "device_id": null, "child_id": null}}',true);
select is((select count(*)::int from public.children),2,'original children preserved on return');
select throws_ok($$select public.select_family('10000000-0000-4000-8000-000000009999')$$,'42501','forbidden','cannot select arbitrary family');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000001303", "role": "authenticated", "is_anonymous": false, "gina": {"family_id": "10000000-0000-4000-8000-000000001301", "role": "device", "device_id": "30000000-0000-4000-8000-000000001301", "child_id": "20000000-0000-4000-8000-000000001302"}}',true);
select throws_ok($$select public.join_family('FA13AA02')$$,'42501','forbidden','paired child cannot join as parent');
reset role;
select is((select count(*)::int from public.families where id in('10000000-0000-4000-8000-000000001301','10000000-0000-4000-8000-000000001302')),2,'neither family deleted');
select is((select count(*)::int from public.children where id in('20000000-0000-4000-8000-000000001301','20000000-0000-4000-8000-000000001302','20000000-0000-4000-8000-000000001303')),3,'no child merged or deleted');

-- Re-pair is closed until the parent saves access, even on a formerly PIN-free device.
update public.devices set revoked_at=now() where id='30000000-0000-4000-8000-000000001301';
insert into public.device_pairings(code,auth_user_id,device_name) values('907813','00000000-0000-4000-8000-000000001303','Re-paired');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001301","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000001301"}}',true);
select is(public.pair_child_device('907813'),'30000000-0000-4000-8000-000000001301'::uuid,'revoked device can pair again');
select is(public.get_child_device_access('30000000-0000-4000-8000-000000001301')->>'pin_policy','required','re-pair removes previous PIN exemption');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001303","role":"authenticated","gina":{"role":"device","family_id":"10000000-0000-4000-8000-000000001301","device_id":"30000000-0000-4000-8000-000000001301","child_id":null}}',true);
select is((select count(*)::int from public.children),0,'newly paired device has no profiles until parent configures');
select throws_ok($$select public.child_pin_login('20000000-0000-4000-8000-000000001301','1234')$$,'42501','forbidden','even correct PIN cannot enter before configuration');
reset role;

-- The installed TestFlight 12 client can still pair using the previous RPC.
update public.devices set revoked_at=now() where id='30000000-0000-4000-8000-000000001301';
insert into public.device_pairings(code,auth_user_id,device_name) values('907814','00000000-0000-4000-8000-000000001303','Legacy');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001301","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000001301"}}',true);
select is(public.pair_device('907814'),'30000000-0000-4000-8000-000000001301'::uuid,'legacy client pairing remains compatible');
select is(public.get_child_device_access('30000000-0000-4000-8000-000000001301')->>'pin_policy','existing','legacy pairing keeps previous PIN policy');
select is(public.get_child_device_access('30000000-0000-4000-8000-000000001301')->>'access_mode','all','legacy pairing has profiles without the new configuration screen');
reset role;

select * from finish();
rollback;
